// Reno's Distortion against VEGAS Distortion: output samples recorded from sfppack3_x64.dll's own processing code
// (run on Linux with its math imports pointed at glibc) for five settings; Reno's must be identical.
//   vegasfx_distortion_test
#include "../../src/audiofx/audioplugin.h"
#include "../../src/audiofx/vegasdistortion.h"
#include <cmath>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

using namespace reno;

struct Case { const char* name; const char* settings; std::vector<std::pair<int, double>> want; };

static std::string unhex(const char* h)
{
    std::string b;
    for (size_t k = 0; h[k] && h[k + 1]; k += 2) b.push_back((char)std::stoi(std::string(h + k, 2), nullptr, 16));
    return b;
}

int main()
{
    const std::vector<Case> cases = {
        {"user", "",
         {{1, 0x1.38814c0000000p-16}, {618, 0x1.63c48e0000000p-16}, {1235, -0x1.5b97dc0000000p-14}, {1852, 0x1.00005e0000000p+0}, {2469, 0x1.00010c0000000p+0}, {3086, -0x1.0cf5a60000000p-10}, {3703, 0x1.0000900000000p+0}, {4320, 0x1.0001160000000p+0}, {4937, -0x1.8954a60000000p-8}, {5554, -0x1.d3536c0000000p-8}, {6171, 0x1.0000480000000p+0}, {6788, -0x1.fbd4b20000000p-7}, {7405, 0x1.0000100000000p+0}, {8022, 0x1.0001080000000p+0}, {8639, -0x1.a9ffb40000000p-2}, {9256, -0x1.29a7840000000p+0}}},
        {"fuzz2", "",
         {{1, 0x1.38814c0000000p-16}, {618, 0x1.63c48e0000000p-16}, {1235, -0x1.4925820000000p-14}, {1852, 0x1.3de8da0000000p-13}, {2469, 0x1.1e11e60000000p-14}, {3086, -0x1.33f4920000000p-11}, {3703, 0x1.1dbdf00000000p-9}, {4320, 0x1.628c960000000p-7}, {4937, -0x1.3c53020000000p-9}, {5554, -0x1.6b18b60000000p-9}, {6171, 0x1.46e7ba0000000p-6}, {6788, -0x1.51d3e60000000p-8}, {7405, 0x1.46e7740000000p-6}, {8022, 0x1.9be1d00000000p-2}, {8639, -0x1.c7619c0000000p-3}, {9256, -0x1.29a7840000000p+0}}},
        {"slew25lp", "",
         {{1, 0x1.1d54820000000p-17}, {618, 0x1.52299c0000000p-15}, {1235, -0x1.22eee40000000p-13}, {1852, 0x1.5f00a60000000p-13}, {2469, 0x1.0565120000000p-12}, {3086, -0x1.9b24ca0000000p-10}, {3703, 0x1.33c67a0000000p-10}, {4320, 0x1.aed2940000000p-8}, {4937, -0x1.22a4880000000p-7}, {5554, -0x1.af9ace0000000p-7}, {6171, 0x1.73d52e0000000p-6}, {6788, 0x1.7fe33a0000000p-5}, {7405, 0x1.fa779c0000000p-6}, {8022, -0x1.cf96ce0000000p-5}, {8639, -0x1.ac02b60000000p-1}, {9256, -0x1.f00be00000000p-1}}},
        {"tube", "",
         {{1, 0x1.7be29c0000000p-17}, {618, 0x1.49ee440000000p-15}, {1235, -0x1.ca48e20000000p-14}, {1852, 0x1.c42b0e0000000p-14}, {2469, 0x1.3e22620000000p-11}, {3086, -0x1.b5c3c40000000p-9}, {3703, 0x1.222c4e0000000p-11}, {4320, 0x1.0755820000000p-6}, {4937, -0x1.04115a0000000p-6}, {5554, -0x1.0e1a160000000p-5}, {6171, 0x1.4174ae0000000p-5}, {6788, 0x1.a9eaaa0000000p-6}, {7405, 0x1.6c191c0000000p-6}, {8022, 0x1.d404120000000p-4}, {8639, -0x1.42b4d00000000p-2}, {9256, -0x1.6bac760000000p-1}}},
        {"rand3", "",
         {{1, 0x1.c05d780000000p-11}, {618, 0x1.9011340000000p-8}, {1235, -0x1.ba24460000000p-13}, {1852, 0x1.1796e80000000p-6}, {2469, 0x1.2e3b3e0000000p-6}, {3086, -0x1.d0ad400000000p-10}, {3703, 0x1.8952a60000000p-6}, {4320, 0x1.216c640000000p-5}, {4937, -0x1.163c620000000p-7}, {5554, -0x1.b2dcac0000000p-7}, {6171, 0x1.71da7a0000000p-5}, {6788, 0x1.b92c4a0000000p-7}, {7405, 0x1.276d820000000p-4}, {8022, 0x1.28523e0000000p-2}, {8639, -0x1.5cc1aa0000000p-2}, {9256, -0x1.7b78520000000p-1}}},
    };
    // stereo test signal: a rising sweep and a 440 Hz tone, fading in from -90 dB to +5 dB
    const int n = 4800;
    std::vector<float> l(n), r(n);
    for (int i = 0; i < n; ++i) {
        const double t = i / 48000.0, env = std::pow(10.0, (-90 + 95.0 * i / n) / 20);
        l[i] = (float)(env * std::sin(2 * 3.141592653589793 * (50 + 3000 * t) * t));
        r[i] = (float)(env * 0.7 * std::sin(2 * 3.141592653589793 * 440 * t + 1));
    }
    int failed = 0;
    for (const Case& c : cases) {
        vegdist::Settings s;
        const std::string raw = unhex(c.settings);
        std::memcpy(&s, raw.data(), sizeof s);
        AudioPluginDesc d;
        d.format = "BUILTIN";
        d.uid = "reno.distortion";
        std::string err;
        auto p = builtinAudioCreate(d, &err);
        if (!p || !p->loadState(vegdist::encode(s))) { std::printf("FAIL %s: not made\n", c.name); ++failed; continue; }
        p->activate(48000, 512);
        std::vector<float> L = l, R = r;
        for (int k = 0; k < n; k += 512) p->process(&L[k], &R[k], std::min(512, n - k), k, true);
        int bad = 0;
        for (const auto& w : c.want) {
            const float got = (w.first % 2 ? R : L)[w.first / 2];
            if (got != (float)w.second) {
                if (!bad) std::printf("FAIL %s: sample %d is %.9g, VEGAS %.9g\n", c.name, w.first, got, w.second);
                ++bad;
            }
        }
        std::printf("%s %s (%d samples)\n", bad ? "FAIL" : "PASS", c.name, (int)c.want.size());
        failed += bad != 0;
    }
    std::printf("SUMMARY: %d failed\n", failed);
    return failed ? 1 : 0;
}
